const LEAVE_STATUSES = new Set(['leave', 'leave_adjusted', 'excused']);
const ATTENDED_SESSION_STATUSES = new Set(['completed', 'attended', 'late']);
/** 剩餘堂數顯示：與「已上」一併視為已占用的狀態（缺席通常已扣堂）。 */
